        if (!rst_n) begin
            busy <= 1'b0;
            cnt  <= 3'd0;
        end else if (start && !busy) begin
            // latch operand and mode, assert BUSY
            operand <= data_in;
            mode    <= enc_dec;
            busy    <= 1'b1;
            cnt     <= 3'd0;
