    assign subst[15:8]  = mode ? DEC1[operand[15:8]]  : ENC1[operand[15:8]];
    assign subst[23:16] = mode ? DEC2[operand[23:16]] : ENC2[operand[23:16]];
    assign subst[31:24] = mode ? DEC3[operand[31:24]] : ENC3[operand[31:24]];

